SELECT set_cost_of_sales, set_product_sales, set_returns FROM (SELECT COALESCE(SUM(CASE WHEN account_id IN ('5000', '5010', '5020', '5030', '5040', '5050', '5060', '5070', '5080', '5090') THEN CASE WHEN account_id IN ('5000', '5010', '5020', '5030', '5040', '5050', '5060', '5070', '5080', '5090') THEN CAST(amount AS BIGNUMERIC) END END), 0) AS set_cost_of_sales, COALESCE(SUM(CASE WHEN account_id IN ('4000', '4010', '4020', '4030', '4040', '4050', '4060', '4070', '4080', '4090') THEN CASE WHEN account_id IN ('4000', '4010', '4020', '4030', '4040', '4050', '4060', '4070', '4080', '4090') THEN -CAST(amount AS BIGNUMERIC) END END), 0) AS set_product_sales, COALESCE(SUM(CASE WHEN account_id IN ('4900') THEN CASE WHEN account_id IN ('4900') THEN CAST(amount AS BIGNUMERIC) END END), 0) AS set_returns FROM journal WHERE posting_date >= CAST('2025-01-01' AS DATE) AND posting_date < CAST('2025-04-01' AS DATE)) AS scan
